// Stops with a clear message when a setting cannot work.
const s = $('Token Settings').first().json;
const problems = [];
const text = (k) => typeof s[k] === 'string' && s[k].trim() !== '';
for (const k of ['connection_name', 'token_table_name', 'refresh_token_param', 'access_token_field', 'refresh_token_field', 'expires_in_field']) if (!text(k)) problems.push(k + ' is empty');
for (const k of ['login_url', 'refresh_url']) if (!/^https?:\/\/\S+$/i.test(String(s[k] ?? '').trim())) problems.push(k + ' is not an http(s) URL');
for (const k of ['login_extra_fields', 'refresh_extra_fields']) if (!s[k] || typeof s[k] !== 'object' || Array.isArray(s[k])) problems.push(k + ' must be a JSON object, e.g. {}');
for (const k of ['default_lifetime_seconds', 'request_timeout_seconds', 'lock_seconds']) if (!(Number(s[k]) > 0)) problems.push(k + ' must be a number above 0');
if (!['json', 'form'].includes(String(s.request_body_format ?? '').trim().toLowerCase())) problems.push('request_body_format must be json or form');
if (!(Number(s.refresh_before_expiry_seconds) >= 0)) problems.push('refresh_before_expiry_seconds must be 0 or more');
if (!(Number(s.alert_cooldown_minutes) >= 0)) problems.push('alert_cooldown_minutes must be 0 or more');
if (!/^[^@\s]+@[^@\s]+$/.test(String(s.alert_email_to ?? '').trim())) problems.push('alert_email_to is not an email address');
if (problems.length) throw new Error('Token Settings: ' + problems.join('; ') + '.');
return [{ json: { ok: true } }];

// Returns the cached token when it is still valid, otherwise asks for a new one.
const s = $('Token Settings').first().json;
const rejected = String($('When Called by Another Workflow').first().json.rejected_token ?? '').trim();
const rows = $input.all().map((i) => i.json).filter((r) => r.id !== undefined).sort((a, b) => a.id - b.id);
// Two callers starting at the very same moment can each add a row; the oldest one is used.
const row = rows[0];
if (!row) throw new Error('The token row for "' + s.connection_name.trim() + '" could not be read.');
const token = String(row.access_token ?? '');
const expires = row.expires_at ? new Date(row.expires_at).getTime() : NaN;
const valid = token !== '' && token !== rejected && Number.isFinite(expires) && expires - Number(s.refresh_before_expiry_seconds) * 1000 > Date.now();
return [{ json: {
  action: valid ? 'cached' : 'renew',
  row_id: row.id,
  rejected_token: rejected,
  checked_at: new Date().toISOString(),
  access_token: valid ? token : '',
  expires_at: valid ? new Date(expires).toISOString() : '',
  source: 'cache',
} }];

const s = $('Token Settings').first().json;
const chk = $('Check Token').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.id !== undefined);
const row = rows.find((r) => r.id === chk.row_id);
const token = row ? String(row.access_token ?? '') : '';
const expires = row && row.expires_at ? new Date(row.expires_at).getTime() : NaN;
const valid = token !== '' && token !== chk.rejected_token && Number.isFinite(expires) && expires - Number(s.refresh_before_expiry_seconds) * 1000 > Date.now();
const failedAt = row && row.last_error_at ? new Date(row.last_error_at).getTime() : 0;
const failedSinceStart = failedAt > new Date(chk.checked_at).getTime();
const name = s.connection_name.trim();
const found = (extra) => [{ json: { access_token: token, expires_at: new Date(expires).toISOString(), source: 'other_execution', ...extra } }];
const fail = (message) => [{ json: { action: 'fail', message } }];
if (!row) return fail('The token row for "' + name + '" was deleted while this execution was running.');
// This execution holds the lock only if the conditional update above wrote its execution id.
const owned = row.lock_token === String($execution.id) && new Date(row.locked_until).getTime() > Date.now();
// Another execution may have saved a new token between the first check and the lock.
if (valid) return found({ action: owned ? 'release' : 'return' });
if (failedSinceStart) return fail('Another execution failed to get a token for "' + name + '" a moment ago: ' + row.last_error);
if (!owned) return [{ json: { action: 'wait' } }];
const refreshToken = String(row.refresh_token ?? '');
return [{ json: { action: refreshToken ? 'refresh' : 'login', refresh_token: refreshToken } }];

const s = $('Token Settings').first().json;
const chk = $('Check Token').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.id !== undefined);
const row = rows.find((r) => r.id === chk.row_id);
const token = row ? String(row.access_token ?? '') : '';
const expires = row && row.expires_at ? new Date(row.expires_at).getTime() : NaN;
const valid = token !== '' && token !== chk.rejected_token && Number.isFinite(expires) && expires - Number(s.refresh_before_expiry_seconds) * 1000 > Date.now();
const failedAt = row && row.last_error_at ? new Date(row.last_error_at).getTime() : 0;
const failedSinceStart = failedAt > new Date(chk.checked_at).getTime();
const name = s.connection_name.trim();
const found = (extra) => [{ json: { access_token: token, expires_at: new Date(expires).toISOString(), source: 'other_execution', ...extra } }];
const fail = (message) => [{ json: { action: 'fail', message } }];
if (!row) return fail('The token row for "' + name + '" was deleted while this execution was running.');
// Waits for the execution that holds the lock: its new token, its error, or the lock running out.
if (valid) return found({ action: 'return' });
if (failedSinceStart) return fail('Another execution failed to get a token for "' + name + '" a moment ago: ' + row.last_error);
const lockSeconds = Math.max(Number(s.lock_seconds) || 60, 2 * (Number(s.request_timeout_seconds) || 15) + 10);
const lockedUntil = row.locked_until ? new Date(row.locked_until).getTime() : 0;
if (lockedUntil <= Date.now() || Date.now() - new Date(chk.checked_at).getTime() > (lockSeconds + 10) * 1000) {
  return fail('The execution refreshing the token for "' + name + '" did not finish within lock_seconds. The next call tries again.');
}
return [{ json: { action: 'wait' } }];

// Reads the token fields from the refresh response (field names and dot paths from Token Settings).
const s = $('Token Settings').first().json;
const r = $input.first().json;
const pick = (obj, path) => String(path).trim().split('.').reduce((o, k) => (o !== null && typeof o === 'object' ? o[k] : undefined), obj);
const fail = (error) => [{ json: { ok: false, method: 'refresh', error } }];
if (r.statusCode === undefined) {
  const e = r.error || {};
  return fail('refresh request failed: ' + String(e.message || e.description || JSON.stringify(e)).slice(0, 300));
}
const code = Number(r.statusCode);
const text = typeof r.body === 'string' ? r.body : JSON.stringify(r.body ?? '');
if (code < 200 || code > 299) return fail('refresh answered HTTP ' + code + ': ' + text.slice(0, 300));
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { return fail('refresh response is not JSON.'); } }
const rawToken = pick(body, s.access_token_field);
// Some APIs return the token with its scheme ("Bearer abc"); the scheme is removed so callers never get "Bearer Bearer abc".
const accessToken = typeof rawToken === 'string' ? rawToken.trim().replace(/^bearer\s+/i, '') : '';
if (accessToken === '') return fail('refresh response has no "' + s.access_token_field + '" text field.');
const newRefresh = pick(body, s.refresh_token_field);
const expiresIn = Number(pick(body, s.expires_in_field));
return [{ json: {
  ok: true,
  method: 'refresh',
  access_token: accessToken,
  // Keep the old refresh token when a refresh answer has none; a login answer without one means "log in again next time".
  refresh_token: typeof newRefresh === 'string' && newRefresh.trim() !== '' ? newRefresh.trim() : $('Decide After Lock').first().json.refresh_token,
  expires_in: Number.isFinite(expiresIn) && expiresIn > 0 ? expiresIn : Number(s.default_lifetime_seconds),
} }];

// Reads the token fields from the login response (field names and dot paths from Token Settings).
const s = $('Token Settings').first().json;
const r = $input.first().json;
const pick = (obj, path) => String(path).trim().split('.').reduce((o, k) => (o !== null && typeof o === 'object' ? o[k] : undefined), obj);
const fail = (error) => [{ json: { ok: false, method: 'login', error } }];
if (r.statusCode === undefined) {
  const e = r.error || {};
  return fail('login request failed: ' + String(e.message || e.description || JSON.stringify(e)).slice(0, 300));
}
const code = Number(r.statusCode);
const text = typeof r.body === 'string' ? r.body : JSON.stringify(r.body ?? '');
if (code < 200 || code > 299) return fail('login answered HTTP ' + code + ': ' + text.slice(0, 300));
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { return fail('login response is not JSON.'); } }
const rawToken = pick(body, s.access_token_field);
// Some APIs return the token with its scheme ("Bearer abc"); the scheme is removed so callers never get "Bearer Bearer abc".
const accessToken = typeof rawToken === 'string' ? rawToken.trim().replace(/^bearer\s+/i, '') : '';
if (accessToken === '') return fail('login response has no "' + s.access_token_field + '" text field.');
const newRefresh = pick(body, s.refresh_token_field);
const expiresIn = Number(pick(body, s.expires_in_field));
return [{ json: {
  ok: true,
  method: 'login',
  access_token: accessToken,
  // Keep the old refresh token when a refresh answer has none; a login answer without one means "log in again next time".
  refresh_token: typeof newRefresh === 'string' && newRefresh.trim() !== '' ? newRefresh.trim() : '',
  expires_in: Number.isFinite(expiresIn) && expiresIn > 0 ? expiresIn : Number(s.default_lifetime_seconds),
} }];

// The new token and its expiry time.
const t = $input.first().json;
return [{ json: { ...t, expires_at: new Date(Date.now() + t.expires_in * 1000).toISOString() } }];

// What callers receive.
const s = $('Token Settings').first().json;
const j = $input.first().json;
const fresh = $('Build Token Record').isExecuted ? $('Build Token Record').first().json : null;
// After Release Lock the item is the table row; the token checked under the lock is in Decide After Lock.
const j2 = $prevNode.name === 'Release Lock' ? $('Decide After Lock').first().json : j;
// A new token comes from Build Token Record (also when saving it failed); other paths carry it in their item.
const t = fresh ? { access_token: fresh.access_token, expires_at: fresh.expires_at, source: fresh.method } : { access_token: j2.access_token, expires_at: new Date(j2.expires_at).toISOString(), source: j2.source };
return [{ json: { connection_name: s.connection_name.trim(), access_token: t.access_token, authorization: 'Bearer ' + t.access_token, expires_at: t.expires_at, source: t.source } }];
